// Report account balances from a ledger file.

const amount_pattern = /^(\d+)\.(\d{2})$/;

// Parse "12.05" into exact cents (1205n). Amounts carry no sign and exactly
// two fraction digits, so no floating point is involved.
function to_cents(amount: string): bigint {
  const match = amount_pattern.exec(amount);
  if (match == null) {
    throw new Error(`bad amount: ${amount}`);
  }
  return BigInt(match[1]) * 100n + BigInt(match[2]);
}

function format_cents(cents: bigint): string {
  const sign = cents < 0n ? "-" : "";
  const abs = cents < 0n ? -cents : cents;
  const fraction = String(abs % 100n).padStart(2, "0");
  return `${sign}${abs / 100n}.${fraction}`;
}

// Compare strings by their UTF-8 bytes, not by UTF-16 code units.
function compare_bytes(left: string, right: string): number {
  const a = new TextEncoder().encode(left);
  const b = new TextEncoder().encode(right);
  const shared = Math.min(a.length, b.length);
  for (let index = 0; index < shared; index++) {
    if (a[index] != b[index]) {
      return a[index] - b[index];
    }
  }
  return a.length - b.length;
}

// Order by balance descending, then account name ascending by bytes.
function by_balance(
  left: [string, bigint],
  right: [string, bigint],
): number {
  if (left[1] != right[1]) {
    return left[1] > right[1] ? -1 : 1;
  }
  return compare_bytes(left[0], right[0]);
}

function read_ledger(path: string): string[] {
  return Deno.readTextFileSync(path)
    .split("\n")
    .map((line) => line.replace(/\r$/, ""));
}

function main() {
  const lines = read_ledger(Deno.args[0]);
  const header = lines[0]?.trim().split(/\s+/) ?? [];
  const n = header.length >= 2 ? Number(header[1]) : 0;

  const balances = new Map<string, bigint>();
  let count = 0;
  for (let index = 1; index < lines.length && count < n; index++) {
    const text = lines[index].trim();
    if (text == "") {
      continue;
    }
    count = count + 1;

    const fields = text.split(/\s+/);
    const kind = fields[fields.length - 2];
    const amount = fields[fields.length - 1];
    const account = fields.slice(0, fields.length - 2).join(" ");

    if (kind != "debit" && kind != "credit") {
      console.log(`ERROR line ${count}`);
      return;
    }

    const amount_cents = to_cents(amount);
    const signed = kind == "credit" ? amount_cents : -amount_cents;
    balances.set(account, (balances.get(account) ?? 0n) + signed);
  }

  const entries = [...balances.entries()].sort(by_balance);
  let total = 0n;
  const out: string[] = [];
  for (const [account, balance] of entries) {
    out.push(`${account} ${format_cents(balance)}`);
    total = total + balance;
  }
  out.push(`TOTAL ${format_cents(total)}`);
  console.log(out.join("\n"));
}

main();

